import { expect, test } from "../../fixtures/test";
import { randomInt } from "node:crypto";
import { parse } from "lossless-json";

// Random ID so tests don't collide with each other or with other users of the shared demo site.
// Kept below Number.MAX_SAFE_INTEGER so JavaScript doesn't round it when parsing responses.
function uniquePetId(): number {
    return randomInt(1000, 2 ** 48);
}

test.describe("Pets API", () => {
    // ID of the pet the current test created, so afterEach can delete it even if the test fails.
    // A string when the ID was generated by Petstore, so it isn't rounded.
    let createdPetId: number | string | undefined;

    test.afterEach(async ({ petsApi }) => {
        if (createdPetId) {
            await petsApi.deletePet(createdPetId);
            createdPetId = undefined;
        }
    });

        test("add valid Pet with minimum spec", async ({
        petsApi, }) => {
        const pet  =   {
                "name": "minimum pet",
                photoUrls: ["https://example.com/rex-1.jpg"]
        };
        // No id is sent, so Petstore generates one near the int64 maximum. JSON.parse would round it,
        // so lossless-json is used to read it with its exact digits (as a string).
        const response = await petsApi.addPet(pet);
        const text = await response.text();
        expect(response.status()).toBe(200);
        const petId = (parse(text) as { id: object }).id.toString();
        createdPetId = petId;
        expect(JSON.parse(text)).toMatchObject(pet);

        // Verify it was stored, not just echoed back
        const fetched = await petsApi.getPet(petId);
        const fetchedText = await fetched.text();
        expect(fetched.status()).toBe(200);
        expect((parse(fetchedText) as { id: object }).id.toString()).toBe(petId);
        expect(JSON.parse(fetchedText)).toMatchObject(pet);
    });


    test("a fully specified pet is created with every field stored", async ({ petsApi }) => {
        const pet = {
            id: uniquePetId(),
            category: { id: 1, name: "Dogs" },
            name: "full-spec-pet",
            photoUrls: ["https://example.com/rex-1.jpg", "https://example.com/rex-2.jpg"],
            tags: [{ id: 1, name: "friendly" }, { id: 2, name: "vaccinated" }],
            status: "available",
        };
        createdPetId = pet.id;

        const response = await petsApi.addPet(pet);
        expect(response.status()).toBe(200);
        expect(await response.json()).toMatchObject(pet);

        // Verify it was stored, not just echoed back
        const fetched = await petsApi.getPet(pet.id);
        expect(fetched.status()).toBe(200);
        expect(await fetched.json()).toMatchObject(pet);
    });

    // These tests assert what Petstore currently returns, so a change in its error handling is noticed.
    // Where that differs from a correct response, the comment above the assertion says what it should be.
    test.describe("Invalid requests", () => {

        test('a request with no body is rejected with 405 "no data"', async ({ petsApi }) => {
            const response = await petsApi.addPetRaw("");
            const body = await response.text();

            // Correct: the spec documents 405 Invalid input for this endpoint.
            // (400 Bad Request would be more conventional, as 405 normally means "method not allowed".)
            expect(response.status(), `Response body: ${body}`).toBe(405);
            expect(JSON.parse(body)).toMatchObject({ code: 405, message: "no data" });
        });

        test('malformed JSON is rejected with 400 "bad input" and no pet is created', async ({ petsApi }) => {
            const petId = uniquePetId();
            createdPetId = petId;   // in case it's unexpectedly created

            // Missing closing brace
            const response = await petsApi.addPetRaw(`{"id": ${petId}, "name": "broken", "photoUrls": []`);
            const body = await response.text();

            // Spec says 405 Invalid input; 400 Bad Request is the conventional code for unparseable JSON.
            // The message doesn't say what was wrong; a correct response would point to the parse error.
            expect(response.status(), `Response body: ${body}`).toBe(400);
            expect(JSON.parse(body)).toMatchObject({ code: 400, message: "bad input" });

            const fetched = await petsApi.getPet(petId);
            expect(fetched.status()).toBe(404);
        });

        test('a non-numeric id fails with 500 "something bad happened"', async ({ petsApi }) => {
            const response = await petsApi.addPet({ id: "abc", name: "bad-id-pet", photoUrls: [] });
            const body = await response.text();

            // DEFECT: should be 400 Bad Request with a message saying id must be an integer.
            // A 500 means the server failed to handle the input rather than validating it.
            expect(response.status(), `Response body: ${body}`).toBe(500);
            expect(JSON.parse(body)).toMatchObject({ code: 500, message: "something bad happened" });
        });

        test("a pet with no name is accepted with 200", async ({ petsApi }) => {
            const pet = { id: uniquePetId(), photoUrls: [] };
            createdPetId = pet.id;

            const response = await petsApi.addPet(pet);
            const body = await response.text();

            // DEFECT: name is required by the spec, so this should be rejected with 405 Invalid input
            // (or 400 Bad Request with a message naming the missing field), and no pet should be created.
            expect(response.status(), `Response body: ${body}`).toBe(200);
        });

        // Playwright always sends a Content-Type when there's a body (application/octet-stream if none is set),
        // so octet-stream stands in for "no Content-Type".
        for (const contentType of ["text/plain", "application/octet-stream"]) {
            test(`a body sent as ${contentType} is rejected with 415 and no pet is created`, async ({ petsApi }) => {
                const petId = uniquePetId();
                createdPetId = petId;   // in case it's unexpectedly created

                const response = await petsApi.addPetRaw(
                    JSON.stringify({ id: petId, name: "wrong-type-pet", photoUrls: [] }),
                    contentType,
                );
                const body = await response.text();

                // Correct status: 415 Unsupported Media Type.
                // The body is XML with no message, unlike the JSON errors elsewhere; a correct response would
                // say which content types are supported (application/json, application/xml).
                expect(response.status(), `Response body: ${body}`).toBe(415);
                expect(body).toContain("<type>unknown</type>");

                const fetched = await petsApi.getPet(petId);
                expect(fetched.status()).toBe(404);
            });
        }
    });
});
